// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for M15: HAR and curl specs, templates, replay, stale signature, TLS-bypass refusal
// Flo: parse specs > replay against the mock API > assert stored record, typed errors, no network on refusal
// I/O: mock server > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const spec = @import("pa-spec-read.zig"); const repl = @import("ct-spec-repl.zig"); const rigz = @import("te-brow-rig.zig");
const allo = std.testing.allocator;
const HAR = "{\"log\":{\"entries\":[{\"request\":{\"method\":\"GET\",\"url\":\"http://h.test/specapi?page={page}&sig=abc\",\"headers\":[{\"name\":\":authority\",\"value\":\"h.test\"},{\"name\":\"Host\",\"value\":\"h.test\"},{\"name\":\"X-Sig\",\"value\":\"good123\"},{\"name\":\"Accept-Encoding\",\"value\":\"gzip\"}]}}]}}";
const CURL = "curl 'http://h.test/specpost' \\\n  -H 'X-Sig: good123' \\\n  -H $'Content-Type: application/json' \\\n  -b 'sid=1' --compressed \\\n  --data-raw '{\"q\":\"{term}\"}'";
test "HAR: method, url, filtered headers" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const spc = try spec.specRead(aren.allocator(), HAR); try std.testing.expectEqualStrings("GET", spc.meth); try std.testing.expectEqual(@as(usize, 1), spc.hdrs.len); try std.testing.expectEqualStrings("X-Sig", spc.hdrs[0].name); }
test "curl: continuation lines, ansi quotes, cookie, data makes POST" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const spc = try spec.specRead(aren.allocator(), CURL); try std.testing.expectEqualStrings("POST", spc.meth); try std.testing.expectEqualStrings("http://h.test/specpost", spc.urlz); try std.testing.expectEqualStrings("{\"q\":\"{term}\"}", spc.body); var cookie = false; for (spc.hdrs) |hd| { if (std.mem.eql(u8, hd.name, "Cookie")) cookie = true; } try std.testing.expect(cookie); try std.testing.expectEqual(@as(usize, 3), spc.hdrs.len); }
test "templates: params fill, JSON braces stay, missing param is BadSpec" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const spc = try spec.specFill(aren.allocator(), try spec.specRead(aren.allocator(), CURL), "term=widgets&page=2"); try std.testing.expectEqualStrings("{\"q\":\"widgets\"}", spc.body); try std.testing.expectError(error.BadSpec, spec.specFill(aren.allocator(), try spec.specRead(aren.allocator(), HAR), "other=1")); }
test "garbage and empty specs are BadSpec" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "hello world")); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "")); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "{\"log\":{}}")); try std.testing.expectError(error.BadSpec, spec.specRead(aren.allocator(), "curl")); }
test "TLS bypass flags and insecure captures are refused" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "curl -k 'http://h.test/a'")); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "curl --insecure 'http://h.test/a'")); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "curl --pinnedpubkey sha256//x 'http://h.test/a'")); try std.testing.expectError(error.PinBypass, spec.specRead(aren.allocator(), "{\"log\":{\"entries\":[{\"_securityState\":\"insecure\",\"request\":{\"method\":\"GET\",\"url\":\"http://h.test/\"}}]}}")); }
test "secret query values are hidden from the stored URL, page numbers stay" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const got = try spec.urlSafe(aren.allocator(), "http://h.test/a?page=2&sig=abc&token=zzz&q=x"); try std.testing.expectEqualStrings("http://h.test/a?page=2&q=x", got); }
fn urlOf(rig: *rigz.Rig, aren: std.mem.Allocator, har: bool) ![]const u8 { var buf: [64]u8 = undefined; const base = rig.srv.urlOf(&buf, ""); if (har) return std.fmt.allocPrint(aren, "{{\"log\":{{\"entries\":[{{\"request\":{{\"method\":\"GET\",\"url\":\"{s}/specapi?page={{page}}&sig=abc\",\"headers\":[{{\"name\":\"X-Sig\",\"value\":\"{s}\"}}]}}}}]}}}}", .{ base, "good123" }); return std.fmt.allocPrint(aren, "curl '{s}/specpost' -H 'X-Sig: good123' --data-raw '{{\"q\":\"{{term}}\"}}'", .{base}); }
test "replay: signed header from the spec works, record stored under a secret-free URL" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); const aren = rig.aren.allocator(); const txt = try urlOf(&rig, aren, true); const out = try repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, txt, "page=2", true); try std.testing.expectEqualStrings("new", out.stat); try std.testing.expectEqualStrings("json", out.kind); try std.testing.expect(std.mem.indexOf(u8, out.urlz, "sig=") == null); try std.testing.expect(std.mem.indexOf(u8, out.urlz, "page=2") != null); var stmt = try rig.dbzz.prep("SELECT body FROM reco WHERE urlz LIKE '%page=2%';"); defer stmt.fini(); try std.testing.expect(try stmt.step()); try std.testing.expect(std.mem.indexOf(u8, stmt.colText(0), "\"query\":\"/specapi?page=2&sig=abc\"") != null); const two = try repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, txt, "page=3", true); try std.testing.expectEqualStrings("new", two.stat); }
test "replay POST with a templated body" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); const aren = rig.aren.allocator(); const txt = try urlOf(&rig, aren, false); const out = try repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, txt, "term=widgets", true); try std.testing.expectEqualStrings("new", out.stat); try std.testing.expectEqual(@as(u16, 200), out.code); }
test "stale signature is a typed error and nothing is stored" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); const aren = rig.aren.allocator(); const txt = try urlOf(&rig, aren, true); const stale = try std.mem.replaceOwned(u8, aren, txt, "good123", "old999"); try std.testing.expectError(error.StaleSpec, repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, stale, "page=2", true)); var stmt = try rig.dbzz.prep("SELECT count(*) FROM page;"); defer stmt.fini(); _ = try stmt.step(); try std.testing.expectEqual(@as(i64, 0), stmt.colInt(0)); }
test "refusals never touch the network: bypass spec, missing param, private host" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); const aren = rig.aren.allocator(); try std.testing.expectError(error.PinBypass, repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, "curl -k 'http://127.0.0.1/x'", "", true)); const txt = try urlOf(&rig, aren, true); try std.testing.expectError(error.BadSpec, repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, txt, "", true)); try std.testing.expectError(error.BlockedHost, repl.replay(allo, aren, std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, txt, "page=2", false)); try std.testing.expectEqual(@as(u32, 0), rig.srv.hits.load(.monotonic)); }
